{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table sms_campaign_data as WITH ga_data as ( select to_date(date,\'YYYYMMDD\') as date, operatingsystem as os, sum(totalrevenue) as sms_revenue, COUNT(*) as sms_orders, from snitch_db.maplemonk.ga_app_source_medium_total_revenue where lower(sessionsourcemedium) like \'%sms%\' and lower(sessionsourcemedium) not like \'%whatsapp%\' group by 1, 2 union all select to_date(date,\'YYYYMMDD\') as date, SESSIONPRIMARYCHANNELGROUP as os, sum(totalrevenue) as sms_revenue, COUNT(*) as sms_orders, from snitch_db.maplemonk.ga_web_source_medium_revenue where lower(sessionsourcemedium) like \'%sms%\' and lower(sessionsourcemedium) not like \'%whatsapp%\' group by 1,2 ), sales_data as ( SELECT order_timestamp::date as order_date, count(distinct order_name) as total_orders, sum(ifnull(gross_sales, 0)) as gross_sales from snitch_db.maplemonk.fact_items_snitch group by 1 ), revenue_data AS ( SELECT date, SUM(sms_revenue) AS daily_revenue, SUM(sms_orders) AS daily_orders FROM ga_data GROUP BY date ), revenue_by_period AS ( SELECT date, DATE_TRUNC(\'week\', DATEADD(day, CASE WHEN DAYOFWEEK(date) = 0 THEN -6 ELSE 1-DAYOFWEEK(date) END, date)) AS week_start, DATE_TRUNC(\'month\', date) AS month_start, daily_revenue, daily_orders FROM revenue_data ), clevertap_data AS ( SELECT COALESCE( TRY_TO_DATE(a.RUN_DATE, \'YYYY/MM/DD\'), TRY_TO_DATE(a.RUN_DATE, \'D/M/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'D/MM/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'DD/MM/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY-M-D\'), TRY_TO_DATE(a.RUN_DATE, \'YYYY-MM-DD\'), TRY_TO_DATE(a.RUN_DATE, \'MM/DD/YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'DD-MM-YYYY\'), TRY_TO_DATE(a.RUN_DATE, \'MM-DD-YYYY\') ) AS run_date, a.CAMPAIGN_ID, MAX(a.CAMPAIGN_NAME) AS campaign_name, MAX(CONCAT_WS(CHAR(10) || CHAR(10), a.TITLE, a.MESSAGE)) AS details, max(a.who_query) as segment, ROUND(COALESCE(SUM(a.TOTAL_CLICKED_EVENTS) / NULLIF(SUM(a.TOTAL_DELIVERED_EVENTS), 0) * 100, 0), 6) AS DAILY_CTR, SUM(a.TOTAL_SENT_USERS) AS total_sent_users, SUM(a.TOTAL_DELIVERED_USERS) AS total_delivered_users, SUM(a.TOTAL_CLICKED_USERS) AS total_clicked_users, SUM(a.TOTAL_SENT_EVENTS) AS total_sent_events, SUM(a.TOTAL_CLICKED_EVENTS) AS total_clicked_events, SUM(a.TOTAL_DELIVERED_EVENTS) AS total_delivered_events, SUM(a.click_through_conversion_revenue) AS click_through_conversion_revenue FROM snitch_db.maplemonk.CT_CLEVERTAP_DB a WHERE lower(a.CHANNEL) = \'whatsapp\' GROUP BY run_date, a.CAMPAIGN_ID ), weekly_revenue AS ( SELECT week_start, SUM(daily_revenue) AS weekly_revenue, SUM(daily_orders) AS weekly_orders FROM revenue_by_period GROUP BY week_start ), monthly_revenue AS ( SELECT month_start, SUM(daily_revenue) AS monthly_revenue, SUM(daily_orders) AS monthly_orders FROM revenue_by_period GROUP BY month_start ) SELECT a.*, DENSE_RANK() OVER (ORDER BY DATE_TRUNC(\'week\', a.run_date) DESC) AS week_rank, DENSE_RANK() OVER (ORDER BY DATE_TRUNC(\'month\', a.run_date) DESC) AS month_rank, COALESCE(r.daily_revenue, 0) AS revenue, COALESCE(r.daily_orders, 0) AS orders, COALESCE(m.monthly_revenue, 0) AS monthly_revenue, COALESCE(w.weekly_revenue, 0) AS week_revenue, COALESCE(w.weekly_orders, 0) AS weekly_orders, COALESCE(m.monthly_orders, 0) AS monthly_orders FROM clevertap_data AS a LEFT JOIN revenue_data AS r ON a.run_date = r.date LEFT JOIN weekly_revenue AS w ON DATE_TRUNC(\'week\', DATEADD(day, CASE WHEN DAYOFWEEK(a.run_date) = 0 THEN -6 ELSE 1-DAYOFWEEK(a.run_date) END, a.run_date)) = w.week_start LEFT JOIN monthly_revenue AS m ON DATE_TRUNC(\'month\', a.run_date) = m.month_start;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            